    if on("f_store") and #(d.Inventory or {}) >= 30 and F.due("store") then
        M.inv("CoolerAction", "storeAll")
        LOG("storeAll", #(d.Inventory or {}))
        F.wait("store", 60)
    end
    if on("f_best") then M.fire("BestSetup") task.wait(0.8) end
    if on("f_sell") then
        d = M.refresh() or d
        local keepR = M.num(val("f_sellmax", 4))
        local fav = type(d.CoolerFav) == "table" and d.CoolerFav or {}
        local keys = {}
        for key, c in pairs(d.Cooler) do
            if type(c) == "table" and not fav[key] then
                local r = M.rarity(c.s)
                local mut = c.mu ~= nil and c.mu ~= ""
                local free = M.num(c.n)
                if FS and FS.CoolerFree then local okF, fr = pcall(FS.CoolerFree, c) if okF and tonumber(fr) then free = tonumber(fr) end end
                if free > 0 and r > 0 and r < keepR and not (mut and on("f_keepmut")) then keys[#keys + 1] = key end
            end
        end
        if #keys > 0 then
            local ok, res = M.inv("CoolerAction", "releaseMany", keys)
            if ok and res ~= false and not (type(res) == "table" and res.err) then S.sold = S.sold + #keys LOG("sell", #keys) end
        end
    end
    F.wait("cooler", 30)
end
function F.buyOne(d)
    local money = M.spend() - (F.reserve or 0)
    local c = {}
    local function add(cost, kind, id, fn) cost = M.num(cost) if cost > 0 and cost <= money then c[#c + 1] = { cost = cost, kind = kind, id = id, fn = fn } end end
    if on("u_net") and FS.Nets and F.due("net") then
        local t = M.num(d.NetTier) + 1
        local nx = FS.Nets[t]
        if nx and (not FS.NetRebirthOk or FS.NetRebirthOk(d, t)) and M.num(nx.Cost) > 0 and M.num(nx.Cost) <= M.spend() then
            M.fire("BuyItem", "Net", t)
            F.wait("net", 3)
            S.bought = S.bought + 1
            LOG("buy net", t, tostring(nx.Name), M.short(nx.Cost))
            notify(__T["New net: "] .. tostring(nx.Name))
            return true
        end
    end
    if on("u_upg") and FS.Upgrades then
        for _, u in ipairs(FS.Upgrades) do
            local lv = M.num(d.Upgrades and d.Upgrades[u.Id])
            if lv < M.num(u.Max) and os.clock() >= (F.failId["u" .. u.Id] or 0) and (not FS.UpgradeLevelOk or FS.UpgradeLevelOk(d, u, lv + 1)) then
                local okC, cost = pcall(FS.UpgradeCost, u.Id, lv)
                if okC then add(cost, "upgrade", u.Id, function()
                    M.fire("BuyItem", "Upgrade", u.Id)
                    task.wait(0.8)
                    local d2 = M.refresh()
                    if d2 and M.num(d2.Upgrades and d2.Upgrades[u.Id]) > lv then return true end
                    F.failId["u" .. u.Id] = os.clock() + 60
                    return false
                end) end
            end
        end
    end
    local groups = { { "u_helper", "HelperAction", "Helper", "HelperById", "HelperCost" }, { "u_spear", "SpearAction", "Spear", "SpearById", "SpearCost" }, { "u_boat", "BoatAction", "Boat", "BoatUpgradeById", "BoatCost" } }
    for _, g in ipairs(groups) do
        if on(g[1]) and FS[g[4]] then
            local have = type(d[g[3]]) == "table" and d[g[3]] or {}
            local function try(id)
                return function()
                    local ok, res, msg = M.inv(g[2], "buy", id)
                    local good = ok and res ~= false and res ~= nil and not (type(res) == "table" and (res.ok == false or res.err))
                    if not good then
                        local why = tostring(type(res) == "table" and (res.err or res.msg or res.reason) or msg or res)
                        if why:lower():find("rebirth") then F.failReb[g[3] .. id] = M.num(d.Rebirths)
                        elseif why:lower():find("hull") then F.failReb[g[3] .. id] = "h" .. tostring(have.Hull) else F.failId[g[3] .. id] = os.clock() + 90 end
                        LOG(g[3] .. " fail", id, why)
                    end
                    return good
                end
            end
            local hullCost
            if g[3] == "Boat" and FS.Boat and FS.Boat.Hulls then
                local nh = FS.Boat.Hulls[M.num(have.Hull) + 1]
                if nh and M.num(d.Rebirths) >= M.num(nh.Rebirth) and os.clock() >= (F.failId.BoatHull or 0) then add(nh.Cost, "boat", "Hull", try("Hull")) end
                if M.num(have.Hull) < 1 then hullCost = true end
            end
            if not hullCost then
                for id, def in pairs(FS[g[4]]) do
                    local lv = M.num(have[id])
                    if os.clock() >= (F.failId[g[3] .. id] or 0) and F.failReb[g[3] .. id] ~= M.num(d.Rebirths) and F.failReb[g[3] .. id] ~= "h" .. tostring(have.Hull) and (not def.Max or lv < M.num(def.Max)) then
                        local okC, cost = pcall(FS[g[5]], id, lv)
                        if okC then add(cost, g[3]:lower(), id, try(id)) end
                    end
                end
            end
        end
    end
    if #c == 0 then return false end
    table.sort(c, function(a, b) return a.cost < b.cost end)
    local x = c[1]
    local ok, good = pcall(x.fn)
    if ok and good then S.bought = S.bought + 1 LOG("buy", x.kind, x.id, M.short(x.cost)) end
    return true
end
function F.upgrades()
    local d = M.d()
    if not (d and FS) then F.wait("upg", 10) return end
    F.reserve = 0
    if on("u_rebirth") and FS.CanRebirth and FS.RebirthNeed then
        local okN, need = pcall(FS.RebirthNeed, d, M.num(d.Rebirths) + 1)
        if okN and type(need) == "table" and M.num(d.TotalCaught) >= M.num(need.Caught) then F.reserve = M.num(need.Cash) end
    end
    F.saving = nil
    if on("u_savenet") and on("u_net") and FS.Nets then
        local t = M.num(d.NetTier) + 1
        local nx = FS.Nets[t]
        if nx and M.num(nx.Cost) > 0 and (not FS.NetRebirthOk or FS.NetRebirthOk(d, t)) then
            F.saving = nx
            F.reserve = math.max(F.reserve, M.num(nx.Cost))
        end
    end
    local bought = F.buyOne(d)
    if on("u_skill") and ST and ST.Nodes and M.num(lp:GetAttribute("SkillPoints")) > 0 and F.due("skill") then
        local nodes = {}
        for _, n in ipairs(ST.Nodes) do nodes[#nodes + 1] = n end
        table.sort(nodes, function(a, b) return M.num(a.Cost) * 100 + M.num(a.Order) < M.num(b.Cost) * 100 + M.num(b.Order) end)
        for _, n in ipairs(nodes) do
            local okB, can = pcall(ST.canBuy, d, n.Id)
            if okB and can and os.clock() >= (F.failId["s" .. n.Id] or 0) then
                local ok, res = M.inv("SkillTree", "buy", n.Id)
                if ok and res ~= false and not (type(res) == "table" and (res.ok == false or res.err)) then LOG("skill", n.Id) else F.failId["s" .. n.Id] = os.clock() + 120 end
                break
            end
        end
        F.wait("skill", 5)
    end
    if on("u_potion") and type(d.PotionInv) == "table" and next(d.PotionInv) and F.due("potion") then
        M.inv("Potions", "useAll")
        LOG("potions used")
        F.wait("potion", 120)
    end
    if on("u_rebirth") and FS.CanRebirth and not F.saving then
        local ok, can = pcall(FS.CanRebirth, d)
        if ok and can then
            F.rbSince = F.rbSince or os.clock()
            if not bought or os.clock() - F.rbSince > 25 then
                M.fire("RebirthRequest")
                S.rebirths = S.rebirths + 1
                F.rbSince = nil
                LOG("rebirth", M.num(d.Rebirths) + 1)
                notify(__T["Rebirthed"])
                F.wait("upg", 4)
                return
            end
        else F.rbSince = nil end
    end
    F.wait("upg", bought and 0.3 or 2)
end
function F.traits()
    local d = M.data or {}
    local TM = RS:FindFirstChild("Traits") and gcall(require, RS.Traits)
    if TM and M.num(d.Rebirths) < M.num(TM.NeedRebirth) then F.wait("traits", 60) return end
    local ok, st = M.inv("Traits", "state")
    if not (ok and type(st) == "table") then F.wait("traits", 60) return end
    local rolls = M.num(st.rolls)
    if on("u_troll") and rolls > 0 then
        local okR, res = M.inv("Traits", "roll", rolls >= 10 and 10 or 1)
        if okR and type(res) == "table" and not res.err then
            LOG("trait roll", rolls >= 10 and 10 or 1, tostring(res.best))
            if res.newBest then notify(__T["New best trait"]) end
            st = res
        end
        F.wait("traits", 2)
    else
        F.wait("traits", 60)
    end
    if on("u_tequip") and type(st.owned) == "table" then
        local best = M.num(st.best)
        for _, v in pairs(st.owned) do if M.num(v) > best then best = M.num(v) end end
        if best > 0 and st.trait ~= best then
            local okE, res = M.inv("Traits", "equip", best)
            if okE and type(res) == "table" and not res.err then LOG("trait equip", best) end
        end
    end
end
function F.pets()
    local ok, st = M.inv("Pets", "state")
    if not (ok and type(st) == "table" and type(st.pets) == "table") or not FS then F.wait("pets", 60) return end
    local d = M.data or {}
    local function lvOf(id) local okL, l = pcall(FS.PetLevel, d, id) return okL and M.num(l) > 0 and M.num(l) or (type(st.lv) == "table" and M.num(st.lv[id]) or 1) end
    if on("u_petlv") then
        for id, n in pairs(st.pets) do
            local lv = math.max(1, lvOf(id))
            local need = FS.PetLevelCost and M.num(FS.PetLevelCost(lv)) or 2 * lv
            if M.num(n) - 1 >= need and os.clock() >= (F.failId["p" .. id] or 0) then
                local okU, res = M.inv("Pets", "levelUp", id)
                if okU and not (type(res) == "table" and res.err) and res ~= false then LOG("pet level", id, lv + 1) else F.failId["p" .. id] = os.clock() + 300 end
                task.wait(0.4)
            end
        end
    end
    if on("u_pet") then
        local best, bm
        for id, n in pairs(st.pets) do
            local def = FS.PetById and FS.PetById[id]
            if def and M.num(n) > 0 then
                local okM, m = pcall(FS.PetMultAt, def, lvOf(id))
                m = okM and M.num(m) or M.num(def.Mult)
                if not bm or m > bm then best, bm = id, m end
            end
        end
        if best and st.equip ~= best then
            local okE, res = M.inv("Pets", "equip", best, 1)
            if okE and not (type(res) == "table" and res.err) and res ~= false then LOG("pet equip", best) notify(__T["Equipped best pet"]) end
        end
    end
    F.wait("pets", 60)
end
function F.passes()
