F.codesTried = {}
function F.codes()
    local list, seen = {}, {}
    local function add(c) c = tostring(c) if #c >= 3 and not seen[c:upper()] then seen[c:upper()] = true list[#list + 1] = c end end
    local ul = RS:FindFirstChild("UpdateLog")
    local data = ul and gcall(require, ul)
    local function scan(t, dep)
        if dep > 5 or type(t) ~= "table" then return end
        for k, v in pairs(t) do
            if type(v) == "string" then
                if tostring(k):lower() == "code" then add(v) end
                for c in v:gmatch("CODES?%s*:?%s*([A-Z0-9]+)") do add(c) end
            elseif type(v) == "table" then scan(v, dep + 1) end
        end
    end
    scan(data, 0)
    for _, c in ipairs({ "2MVISITS", "1MVISITS", "500KVISITS", "250KVISITS", "100KVISITS", "ANCIENT", "GENESIS", "ABSOLUTE", "BOUNDLESS", "UPD1", "MONARCH", "SEAMASTER", "MONEY", "LUCKY", "PETFISH", "KRAKEN" }) do add(c) end
    local n = 0
    for _, c in ipairs(list) do
        if not F.codesTried[c] then
            F.codesTried[c] = true
            local ok, res = M.inv("Rewards", "redeem", c)
            if ok and res and res ~= false and not (type(res) == "table" and (res.ok == false or res.err)) then n = n + 1 end
            task.wait(0.6)
        end
    end
    if n > 0 then notify(__T["Redeemed "] .. n .. __T[" codes"]) end
    LOG("codes", #list, n)
end
function F.rewards()
    local ok, st = M.inv("Rewards", "state")
    if ok and type(st) == "table" then
        if on("r_daily") and type(st.daily) == "table" and st.daily.claimable then
            local okD, res = M.inv("Rewards", "claimDaily")
            if okD and res ~= false and not (type(res) == "table" and res.err) then LOG("daily claimed") notify(__T["Daily reward claimed"]) end
        end
        if on("r_gifts") and type(st.gifts) == "table" then
            for i, g in pairs(st.gifts) do
                if type(g) == "table" and g.ready and not g.claimed then
                    if M.inv("Rewards", "claimGift", i) then LOG("gift", i, tostring(g.text)) end
                    task.wait(0.5)
                end
            end
        end
    end
    if on("r_spin") then
        local ok2, rt = M.inv("Retention", "state")
        if ok2 and type(rt) == "table" and type(rt.spin) == "table" and M.num(rt.spin.spins) > 0 then
            local okS, res = M.inv("Retention", "spin")
            if okS and not (type(res) == "table" and res.err) then LOG("spin", M.num(rt.spin.spins)) end
        end
    end
    if on("r_quests") then
        local okC, cs = M.inv("Contracts", "state")
        if okC and type(cs) == "table" and type(cs.list) == "table" then
            for i, q in pairs(cs.list) do
                if type(q) == "table" and not q.done and M.num(q.goal) > 0 and M.num(q.p) >= M.num(q.goal) then
                    local okQ, res = M.inv("Contracts", "claim", i)
                    if okQ and not (type(res) == "table" and res.err) then LOG("contract", i, tostring(q.text)) end
                    task.wait(0.3)
                end
            end
        end
        M.inv("PearlShop", "freeClam")
    end
    F.wait("rewards", 60)
end
