UI.aimmin = rIndex(val("f_aimminN", RAR[3]), 3)
UI.sellmax = rIndex(val("f_sellmaxN", RAR[4]), 4)
Opt.f_aimmin = { Value = UI.aimmin }
Opt.f_sellmax = { Value = UI.sellmax }
task.spawn(function()
    while RUNNING do
        pcall(function()
            Opt.f_aimmin.Value = rIndex(val("f_aimminN", RAR[3]), 3)
            Opt.f_sellmax.Value = rIndex(val("f_sellmaxN", RAR[4]), 4)
            local mins = math.max((os.clock() - S.t0) / 60, 0.25)
            local b = M.base()
            setText(UI.s1, string.format(__T["Cash $%s · +$%s/s"], M.short(M.cash()), M.short(lp:GetAttribute("IncomePerSec") or 0)))
            setText(UI.s2, string.format(__T["Net %s · %s/%s fish"], tostring(b and b:GetAttribute("NetState") or "-"), tostring(b and b:GetAttribute("NetCount") or 0), tostring(b and b:GetAttribute("NetCap") or 0)))
            setText(UI.s3, string.format(__T["Casts %d · Fish %d · Pads $%s"], S.casts, S.fish, M.short(S.collected)))
            setText(UI.s4, string.format(__T["Earned $%s · %dm · %s"], M.short(S.earned), math.floor(mins), tostring(S.task)))
            local now = Workspace:GetServerTimeNow()
            local function tl(k) local v = Workspace:GetAttribute(k) if type(v) ~= "number" then return "-" end local s = math.max(0, v - now) return s >= 60 and string.format("%dm", math.floor(s / 60)) or string.format("%ds", math.floor(s)) end
            setText(UI.e1, string.format(__T["%s · shots %d · hits %d"], F.turret and (__T["Fighting "] .. F.turret) or __T["Waiting"], S.shots or 0, S.hits or 0))
            setText(UI.e2, string.format(__T["Megalodon %s\nBloop %s\nKraken %s\nWave Rush %s"],Workspace:GetAttribute("MegActive") and __T["NOW"] or tl("MegNext"), Workspace:GetAttribute("BloopActive") and __T["NOW"] or tl("BloopNext"), Workspace:GetAttribute("BossActive") and __T["NOW"] or tl("BossNext"), Workspace:GetAttribute("WaveActive") and __T["NOW"] or tl("NextWaveRush")))
            local d = M.data
            if d and FS and FS.RebirthNeed then
                local okN, nx = pcall(FS.RebirthNeed, d, M.num(d.Rebirths) + 1)
                nx = okN and nx or nil
                if type(nx) == "table" then
                    setText(UI.p1, F.saving and string.format(__T["Saving for %s · $%s"], tostring(F.saving.Name), M.short(F.saving.Cost)) or string.format(__T["Rebirth %d · next $%s + %d fish"], M.num(d.Rebirths), M.short(nx.Cash), M.num(nx.Caught)))
                else setText(UI.p1, __T["Rebirth "] .. M.num(d.Rebirths)) end
            end
        end)
        task.wait(0.5)
    end
end)
onClean(function() pcall(function() Library:Unload() end) end)
pcall(function()
    local name, ok, err = SaveManager:GetAutoloadConfig()
    local loaded = false
    if ok and not err then
        loaded = SaveManager:Load(name) == true
        if not loaded then SaveManager.Library:Notify("Autoload config not found, using last settings") end
    end
    if not loaded and isfile and isfile("COMBO_WICK_NF/settings/auto.json") then SaveManager:Load("auto") end
end)
do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() if not SaveManager.Library.Unloaded then SaveManager:Save("auto") end end) end end)
    end
    local function skip(k) k = tostring(k); return k == "f_pause" or k == "MenuKeybind" or k == "r_code" or k == "f_aimmin" or k == "f_sellmax" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) and type(o) == "table" and o.OnChanged then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
function UI.center()
    pcall(function()
        local sg = Library.ScreenGui
        local m = sg and sg:FindFirstChild("Main")
        if not m then return end
        m.AnchorPoint = Vector2.zero
        for _ = 1, 3 do
            local vs, sz, cur = sg.AbsoluteSize, m.AbsoluteSize, m.AbsolutePosition
            local tx, ty = math.max(0, math.floor((vs.X - sz.X) / 2)), math.max(0, math.floor((vs.Y - sz.Y) / 2))
            local k = (m.Size.X.Offset > 0 and sz.X / m.Size.X.Offset) or 1
            if math.abs(cur.X - tx) < 2 and math.abs(cur.Y - ty) < 2 then break end
            m.Position = UDim2.new(m.Position.X.Scale, m.Position.X.Offset + (tx - cur.X) / k, m.Position.Y.Scale, m.Position.Y.Offset + (ty - cur.Y) / k)
            RunService.Heartbeat:Wait()
        end
    end)
end
for _, dl in ipairs({ 1, 3, 6 }) do task.delay(dl, UI.center) end
function UI.fixSize()
    pcall(function()
        local m = Library.ScreenGui and Library.ScreenGui:FindFirstChild("Main")
        local cam = Workspace.CurrentCamera
        if not (m and cam) then return end
        local vs = cam.ViewportSize
        if vs.X >= 300 and vs.Y >= 250 and (m.AbsoluteSize.X < 250 or m.AbsoluteSize.Y < 200) then
            m.Size = UDim2.fromOffset(math.min(580, vs.X - 20), math.min(480, vs.Y - 20))
            task.defer(UI.center)
        end
    end)
end
task.spawn(function() while RUNNING do UI.fixSize() task.wait(1) end end)
task.spawn(function()
    local t0 = os.clock()
    while RUNNING and not M.data and os.clock() - t0 < 30 do task.wait(1) end
    if not REM then
        setText(UI.exec, '<font color="#ff6b6b">' .. __T["Game remotes not found. Rejoin and try again."] .. '</font>')
    elseif not FS then
        setText(UI.exec, '<font color="#ff6b6b">' .. __T["Some features need a better executor."] .. '</font>')
    elseif not M.data then
        setText(UI.exec, '<font color="#ff6b6b">' .. __T["Waiting for your game data..."] .. '</font>')
    else
        setText(UI.exec, '<font color="#7ED957">' .. __T["Executor check: all features supported"] .. '</font>')
    end
end)
notify(__T["Loaded"])

end
